 try {
 flutterFragment?.let { fragment ->
 (context as? FragmentActivity)?.let { activity ->
 if (!fragment.isAdded) {
 activity.supportFragmentManager
 .beginTransaction()
 .replace(view.id, fragment)
 .commit()
 }
