 "ItemsFlutterScreen",
 "No valid FragmentActivity found to host Flutter fragment"
 )
 }
 }
 } catch (e: Exception) {
 Log.e("ItemsFlutterScreen", "Error adding Flutter fragment", e)
 }
 }
 )

