 _updateNativeAppBarTitle("Item ${item['id']}");
 Navigator.of(context).push(
 MaterialPageRoute(
 builder: (context) =>
 ItemDetailScreen(
 itemId: item['id']?.toString() ?? '',
 onBack: () {
 _updateNativeAppBarTitle("Items");
 Navigator.of(context).pop();
 },
 ),
