class ItemsListScreen extends StatelessWidget {
 const ItemsListScreen({super.key});

 @override
 Widget build(BuildContext context) {
 // Example item data
 final items = List.generate(
 20,
 (index) =>
 {
 'id': '${index + 1}',
 'name': 'Item ${index + 1}',
 'description': 'Description for item ${index + 1}',
 'price': '\$${(index + 1) * 10}.99',
