;\n\n runApp(const MyApp());\n}\n\n// Global function to handle back navigation\nFuture<bool> handleSystemBackPress() async {\n debugPrint(\"Handling system back press\");\n \n // First try using the items navigator if it exists and can pop\n if (itemsNavigatorKey.currentState?.canPop() == true) {\n debugPrint(\"Items navigator can pop - popping and updating title to Items\");\n _updateNativeAppBarTitle(\"Items\");\n itemsNavigatorKey.currentState?.pop();\n return true;\n }\n\n // Then try the root navigator\n if (rootNavigatorKey.currentState?.canPop() == true) {\n debugPrint(\"Root navigator can pop - popping\");\n rootNavigatorKey.currentState?.pop();\n return true;\n }\n\n debugPrint(\"No navigator could handle back press\");\n return false;\n}\n\nclass MyApp extends StatelessWidget {\n const MyApp({super.key});\n\n @override\n Widget build(BuildContext context) {\n // Print debug information to help diagnose routing issues\n debugPrint('Building MyApp with initialRoute: ${WidgetsBinding.instance.platformDispatcher\n .defaultRouteName}');\n\n return MaterialApp(\n title: 'Flutter Module',\n debugShowCheckedModeBanner: false,\n theme: ThemeData(\n primarySwatch: Colors.blue,\n useMaterial3: true,\n colorScheme: ColorScheme.fromSeed(seedColor: Colors.blue),\n ),\n navigatorKey: rootNavigatorKey,\n // Use the route provided by the platform if available\n initialRoute: WidgetsBinding.instance.platformDispatcher.defaultRouteName != '/' &&\n WidgetsBinding.instance.platformDispatcher.defaultRouteName != ''\n ? WidgetsBinding.instance.platformDispatcher.defaultRouteName\n : '/profile', // Default to profile route for Items tab\n@@ ... @@\nclass ProfileScreen extends StatelessWidget {\n const ProfileScreen({super.key});\n\n @override\n Widget build(BuildContext context) {\n // Set the title to \"Items\" when this screen is shown\n WidgetsBinding.instance.addPostFrameCallback((_) {\n _updateNativeAppBarTitle(\"Items\");\n debugPrint(\"Profile screen initialized, setting title to Items\");\n });\n\n // Generate the items data\n final items = List.generate(\n 20,\n (index) =>\n {\n 'id': '${index + 1}',\n 'name': 'Item ${index + 1}',\n 'description': 'Description for item ${index + 1}',\n 'price': '\\$${(index + 1) * 10}.99',\n },\n );\n\n // Use a simpler approach - directly show the items list\n return Material(\n color: Colors.white,\n child: SafeArea(\n child: Column(\n crossAxisAlignment: CrossAxisAlignment.start,\n children: [\n // Debug info at the top\n Container(\n padding: const EdgeInsets.all(8),\n color: Colors.amber.shade100,\n width: double.infinity,\n child: Text(\n \"Items List - Route: ${WidgetsBinding.instance.platformDispatcher.defaultRouteName}\",\n style: const TextStyle(fontSize: 12),\n ),\n ),\n // Items list\n Expanded(\n child: ListView.builder(\n itemCount: items.length,\n itemBuilder: (context, index) {\n final item = items[index];\n return ListTile(\n leading: CircleAvatar(\n backgroundColor: Colors.blue.shade100,\n child: Text(item['id']?.toString() ?? ''),\n ),\n title: Text(item['name']?.toString() ?? ''),\n subtitle: Text('Price: ${item['price']?.toString() ?? ''} - Tap for details'),\n onTap: () {\n debugPrint(\"Tapped on item ${item['id']}\");\n _updateNativeAppBarTitle(\"Item ${item['id']}\");\n \n // Use MaterialPageRoute to ensure proper transition\n Navigator.of(context).push(\n MaterialPageRoute(\n builder: (context) =>\n ItemDetailScreen(\n itemId: item['id']?.toString() ?? '',\n onBack: () {\n _updateNativeAppBarTitle(\"Items\");\n Navigator.of(context).pop();\n },\n ),\n settings: RouteSettings(name: '/item/${item['id']}'),\n ),\n );\n },\n );\n },\n ),\n ),\n ],\n ),\n ),\n );\n }\n}\n@@ ... @@\n// Function to communicate with native code to update the app bar title\nvoid _updateNativeAppBarTitle(String title) {\n try {\n debugPrint(\"Updating native app bar title to: $title\");\n channel.invokeMethod('updateTitle', {'title': title}).then((value) {\n debugPrint(\"Native title update complete